// DataTransfer()
DataTransfer(Start_Addr, Size, Length, Data_Bytes, Burst, IsWrite)
// IsWrite is TRUE for a write, and FALSE for a read
addr = Start_Addr; // Variable for current address Aligned_Addr = (INT(addr/Size) * Size);
aligned = (Aligned_Addr == addr); // Check whether addr aligned to Size Container_Size = Size * Length;
if Burst == WRAP then
Lower_Wrap_Boundary = (INT(addr/Container_Size) * Container_Size);
// addr must be aligned for a wrapping burst Upper_Wrap_Boundary = Lower_Wrap_Boundary + Container_Size;
for n = 1 to Length
Lower_Byte_Lane = addr - (INT(addr/Data_Bytes) * Data_Bytes); if aligned then Upper_Byte_Lane = Lower_Byte_Lane + Size - 1 else
Upper_Byte_Lane = Aligned_Addr + Size - 1
- (INT(addr/Data_Bytes) * Data_Bytes);
// Perform data transfer if IsWrite then dwrite(addr, Lower_Byte_Lane, Upper_Byte_Lane)
else dread(addr, Lower_Byte_Lane, Upper_Byte_Lane);
// Increment address if necessary if Burst != FIXED then if aligned then addr = addr + Size; if Burst == WRAP then if addr >= Upper_Wrap_Boundary then addr = Lower_Wrap_Boundary; else addr = Aligned_Addr + Size; aligned = TRUE; // All transfers after the first are aligned
return;
